mapper.select:
select d.*,kb.name as knowledgeName from doc_document d
left join doc_knowledge_base kb on d.kb_id=kb.id


    d.is_deleted=0
    and kb.is_deleted=0


        and d.kb_id =#{map.kbId}


        and d.title like concat('%',#{map.keyword},'%')


        and d.file_type=#{map.fileType}


        and d.parse_status=#{map.parseStatus}




        and (
        d.upload_user_id=#{map.userId}
        or kb.visibility=2
        or (kb.visibility=1 and kb.dept_id in (select dept_id from sys_user where id=#{map.userId}))
        )


order by d.create_time desc

select * from doc_document d left join doc_knowledge_base kb on d.kb_id=kb.id

             d.is_deleted=0
             and d.kb_id=#{kbId}

            and (
            d.upload_user_id=#{currentId}
            or kb.visibility=2
            or (kb.visibility=1 and kb.dept_id in (select dept_id from sys_user where id=#{currentId}))
            )
